{
  "avaliacoes": [
    {
      "id": "E5723d828b24105a6",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "No escoamento do petróleo até as unidades de tratamento primário, a formação de emulsões aparece como um dos desafios de garantia de escoamento, ao lado de parafinas, asfaltenos, hidratos e incrustações.",
          "trechos": [
            "E5723d828b24105a6:0:691"
          ],
          "condicoes": [
            "Aplicável ao escoamento do reservatório até as unidades de tratamento primário",
            "Contexto destacado para águas profundas e arranjos de longo percurso"
          ],
          "limites": [
            "O trecho apresenta visão geral de desafios operacionais, sem critérios de seleção de químicos, dosagens ou métodos de controle"
          ]
        },
        {
          "proposicao": "Emulsões água-em-óleo podem se formar pelo escoamento simultâneo dos fluidos e por propriedades físico-químicas do petróleo, e sua estabilidade pode aumentar a viscosidade e afetar perda de carga e capacidade dos sistemas de produção.",
          "trechos": [
            "E5723d828b24105a6:691:1390"
          ],
          "condicoes": [
            "Referido ao processo de produção do petróleo",
            "Especialmente relevante em sistemas offshore"
          ],
          "limites": [
            "Não quantifica o aumento de viscosidade nem define limites operacionais"
          ]
        },
        {
          "proposicao": "Compostos heteroatômicos e funcionalizados presentes no petróleo têm atividade interfacial, podendo influenciar formação de emulsões, espuma e molhabilidade da rocha; o texto destaca os ácidos carboxílicos como classe de interesse.",
          "trechos": [
            "E5723d828b24105a6:1390:2085",
            "E5723d828b24105a6:2085:2424"
          ],
          "condicoes": [
            "Quando o petróleo entra em contato com água ou sólidos durante o processamento primário"
          ],
          "limites": [
            "Não explicita compatibilidade química com produtos injetados nem desempenho de desemulsificantes específicos"
          ]
        }
      ]
    },
    {
      "id": "E42fd6bb742f47e9b",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A formação e a estabilidade de emulsões durante a produção podem alterar as propriedades da fase líquida, modificando condições de deposição de parafinas, asfaltenos e incrustações de sais, além de complicar corrosão de linhas e separação água-óleo.",
          "trechos": [
            "E42fd6bb742f47e9b:696:1393"
          ],
          "condicoes": [
            "Durante a produção de petróleo",
            "Relacionada à alteração das propriedades da fase líquida"
          ],
          "limites": [
            "O trecho sugere interações operacionais, mas não estabelece hierarquia causal universal nem método de mitigação"
          ]
        },
        {
          "proposicao": "A emulsificação do óleo pode ser promovida pelo cisalhamento imposto por bombas, válvulas, acidentes na linha e outros equipamentos de processo.",
          "trechos": [
            "E42fd6bb742f47e9b:1393:2082"
          ],
          "condicoes": [
            "Durante o processo de produção"
          ],
          "limites": [
            "Não diferencia intensidades de cisalhamento nem condições de cada equipamento"
          ]
        },
        {
          "proposicao": "Partículas sólidas finamente divididas da formação produtora e moléculas tensoativas naturais do petróleo podem aumentar a produção e a estabilidade do óleo emulsificado nas águas oleosas; emulsificantes estabilizam a emulsão ao formar filme interfacial na interface água-óleo.",
          "trechos": [
            "E42fd6bb742f47e9b:1393:2082",
            "E42fd6bb742f47e9b:2082:2380"
          ],
          "condicoes": [
            "Na presença de sólidos finos e compostos com atividade interfacial"
          ],
          "limites": [
            "Não informa quais sólidos ou tensoativos são dominantes em cada caso nem como isso afeta a seleção de químicos"
          ]
        }
      ]
    },
    {
      "id": "Eac5352692e9e8c2a",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A água produzida pode conter produtos químicos adicionados ao processo, incluindo coagulantes, floculantes, inibidores de incrustação e corrosão, biocidas, surfactantes, quebradores de emulsão e de espuma, agentes controladores de parafinas, ácidos, sequestradores de oxigênio e redutores de fricção.",
          "trechos": [
            "Eac5352692e9e8c2a:0:698",
            "Eac5352692e9e8c2a:698:1393"
          ],
          "condicoes": [
            "No contexto de operações de produção e tratamento da água produzida"
          ],
          "limites": [
            "O trecho lista classes químicas presentes ou usadas, mas não traz compatibilidades entre elas nem dosagens"
          ]
        },
        {
          "proposicao": "A origem de metais na água de produção pode estar tanto nas formações geológicas quanto na corrosão dos equipamentos e no próprio óleo cru, que contém diversos metais pesados.",
          "trechos": [
            "Eac5352692e9e8c2a:0:698"
          ],
          "condicoes": [
            "Quando se analisa a composição da água de produção"
          ],
          "limites": [
            "Não distingue contribuição relativa de cada origem em diferentes instalações"
          ]
        },
        {
          "proposicao": "Além de sais, metais, sólidos em suspensão e traços de radionuclídeos, a água produzida pode carregar quebradores de emulsão e de espuma e outros químicos de processo, o que mostra a interface entre tratamento químico e composição do efluente a tratar.",
          "trechos": [
            "Eac5352692e9e8c2a:698:1393",
            "Eac5352692e9e8c2a:1393:2091"
          ],
          "condicoes": [
            "Para correntes de água produzida destinadas ao tratamento"
          ],
          "limites": [
            "Não informa efeitos de compatibilidade desses químicos sobre etapas subsequentes de separação ou descarte"
          ]
        }
      ]
    },
    {
